infra/aws/terraform/amgt-resapp/chatter-.text:
# AMGT_RESAPP -- THE CHATTER AXIS WRITER, its schedule (cell AMGT-rd-5, round 5/v5, row
# S16, FWD-15). A SCHEDULED PRODUCER, never a monitor -- standing moratorium forbids an
# alert/alarm/SNS/SES-send/freshness-checker/monitor; nothing in this file or the Lambda
# it deploys watches opal-amgt-security-metrics or notifies anyone. It only computes the
# chatter ranking (30-day window, 0-100 normalized, TOP_N=10 -- lib/research/metrics/
# chatter_gate.py is the one place those numbers live) and writes pre-computed rows.
#
# NO NEW `terraform{}` / `provider "aws"{}` / `backend{}` BLOCK IN THIS FILE, ON PURPOSE
# (task-order BLOCK + surprise rows AMGT_RESAPP-Z-S9/-S10: this module directory already
# carries a live provider/backend collision between AMGT-rd-1's and AMGT-rd-2's own
# files, routed to AMGT-rd-3 for reconcile -- NOT this cell's to touch). This file relies
# entirely on the `terraform{}`/`provider "aws"{}` blocks already declared in
# security-metrics-table.tf (AMGT-rd-2, same directory) -- a Terraform module shares one
# provider configuration across every .tf file in its directory; adding a second
# declaration here would only make that collision worse, so this file adds none.
#
# THE LAMBDA'S SOURCE IS NOT HAND-DUPLICATED, BUT IS NOT `archive_file` EITHER --
# MEASURED, NOT ASSUMED: this module directory has exactly ONE `required_providers`
# block (security-metrics-table.tf:49, AMGT-rd-2's own file, which this cell's task
# order BLOCKS touching -- surprise rows AMGT_RESAPP-Z-S9/-S10, routed to AMGT-rd-3).
# `terraform init` run directly against this directory with a SECOND
# `required_providers` block added (for the `archive` provider, which `archive_file`
# needs) refused hard: "Error: Duplicate required providers configuration ... A module
# may have only one required providers configuration." (this cell's session log) --
# not a style question, a Terraform error. So instead: lambda_src/build_zip.py builds
# the deployment zip OUTSIDE Terraform, from the exact same three sources
# (lambda_function.py, lib/research/metrics/chatter_gate.py, chatter_axis.py) plus a
# frozen universe.json snapshot, and this file references the resulting static zip via
# Terraform's BUILT-IN `filebase64sha256()` -- no provider requirement at all. Re-run
# build_zip.py after any change to those source files, then re-apply; the changed
# source_code_hash is what tells Terraform the function changed.
locals {
  chatter_axis_zip = "${path.module}/.build/chatter-axis-producer.zip"
}

data "aws_caller_identity" "chatter_axis_current" {}

# ---------------------------------------------------------------- lambda execution role
#
# Least-privilege, three grants only: (1) query opal-amgt-articles' ticker_date_index
# GSI (read-only, the raw chatter signal), (2) write opal-amgt-security-metrics (the
# axis's own output table), (3) its own CloudWatch Logs stream (the standard Lambda
# execution grant every function needs to run at all -- NOT a monitor/alarm; nobody
# reads these logs automatically and nothing here alerts on their content).
resource "aws_iam_role" "chatter_axis_lambda" {
  name = "amgt-resapp-chatter-axis-lambda-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [{ Effect = "Allow", Principal = { Service = "lambda.amazonaws.com" }, Action = "sts:AssumeRole" }]
  })
  tags = {
    pipeline = "amgt-resapp"
    cell     = "AMGT-rd-5"
  }
}

resource "aws_iam_role_policy" "chatter_axis_lambda" {
  name = "amgt-resapp-chatter-axis-lambda-policy"
  role = aws_iam_role.chatter_axis_lambda.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadArticlesTickerDateIndex"
        Effect   = "Allow"
        Action   = ["dynamodb:Query"]
        Resource = [
          "arn:aws:dynamodb:us-east-1:${data.aws_caller_identity.chatter_axis_current.account_id}:table/opal-amgt-articles",
          "arn:aws:dynamodb:us-east-1:${data.aws_caller_identity.chatter_axis_current.account_id}:table/opal-amgt-articles/index/ticker_date_index",
        ]
      },
      {
        Sid      = "WriteSecurityMetrics"
        Effect   = "Allow"
        Action   = ["dynamodb:PutItem", "dynamodb:BatchWriteItem"]
        Resource = [aws_dynamodb_table.security_metrics.arn]
      },
      {
        Sid      = "OwnLogStreamOnly"
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          "arn:aws:logs:us-east-1:${data.aws_caller_identity.chatter_axis_current.account_id}:log-group:/aws/lambda/amgt-resapp-chatter-axis:*",
        ]
      },
    ]
  })
}

resource "aws_lambda_function" "chatter_axis_producer" {
  function_name    = "amgt-resapp-chatter-axis"
  role             = aws_iam_role.chatter_axis_lambda.arn
  handler          = "lambda_function.handler"
  runtime          = "python3.12"
  filename         = local.chatter_axis_zip
  source_code_hash = filebase64sha256(local.chatter_axis_zip)

  # A daily COUNT-only GSI query over ~34 tickers plus <=10 PutItem calls -- small,
  # bounded work with no long-poll step (unlike the astn/estate-report reference shapes
  # that wait on an EC2 job). 60s is generous headroom, not a load-bearing ceiling.
  timeout     = 60
  memory_size = 128

  tags = {
    pipeline = "amgt-resapp"
    cell     = "AMGT-rd-5"
  }
}

# ---------------------------------------------------------------- scheduler -> lambda
resource "aws_iam_role" "chatter_axis_scheduler" {
  name = "amgt-resapp-chatter-axis-scheduler-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [{ Effect = "Allow", Principal = { Service = "scheduler.amazonaws.com" }, Action = "sts:AssumeRole" }]
  })
  tags = {
    pipeline = "amgt-resapp"
    cell     = "AMGT-rd-5"
  }
}

resource "aws_iam_role_policy" "chatter_axis_scheduler" {
  name = "amgt-resapp-chatter-axis-scheduler-invoke"
  role = aws_iam_role.chatter_axis_scheduler.id
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [{ Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.chatter_axis_producer.arn] }]
  })
}

# DAILY, a real clock trigger -- NOT success-of-upstream (this axis has no upstream job to
# await; it is a root producer over opal-amgt-articles + the landed universe). 10:00 UTC:
# after the prior UTC day's press cycle has largely landed and before the US session opens
# -- an operational cadence choice, not one of the three given axis numbers (window/scale/
# TOP_N), which stay exactly as chatter_gate.py declares them.
resource "aws_scheduler_schedule" "chatter_axis_daily" {
  name                         = "amgt-resapp-chatter-axis-daily"
  state                        = "ENABLED"
  schedule_expression          = "cron(0 10 * * ? *)"
  schedule_expression_timezone = "UTC"

  flexible_time_window { mode = "OFF" }

  target {
    arn      = aws_lambda_function.chatter_axis_producer.arn
    role_arn = aws_iam_role.chatter_axis_scheduler.arn
  }
}

output "chatter_axis_lambda_arn" {
  value = aws_lambda_function.chatter_axis_producer.arn
}

output "chatter_axis_schedule_state" {
  value = aws_scheduler_schedule.chatter_axis_daily.state
}
